async function getQuote(id) {
  const ac = new AbortController();
  const t = setTimeout(() => ac.abort(), 800);
  const res = await fetch(`${PRICING}/quotes/${id}`, { signal: ac.signal });
  clearTimeout(t);
  return res.json();
}

